// Get all models from Google Sheets
const models = $input.all();

// Format for Claude
const modelLibrary = models.map(item => {
  const data = item.json;
  return {
    id: parseInt(data.ID),
    name: data.Name,
    url: data.URL,
    gridSize: {
      x: parseInt(data.GridX),
      y: parseInt(data.GridY)
    },
    category: data.Category,
    tags: data.Tags.split(',').map(t => t.trim())
  };
});

// Get user prompt from webhook
const userPrompt = $('Webhook').item.json.body.prompt;

// Return formatted data
return {
  json: {
    prompt: userPrompt,
    modelLibrary: modelLibrary,
    totalModels: modelLibrary.length
  }
};

// Get Claude API response
const claudeResponse = $input.item.json;

// Extract content from Claude's response
const content = claudeResponse.content[0].text;

// Parse JSON from Claude's response
let sceneData;
try {
  // Claude sometimes wraps in markdown, clean it
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    sceneData = JSON.parse(jsonMatch[0]);
  } else {
    sceneData = JSON.parse(content);
  }
} catch (error) {
  throw new Error(`Failed to parse Claude response: ${error.message}\nResponse: ${content}`);
}

// Validate required fields
if (!sceneData.sceneConfig || !sceneData.objects) {
  throw new Error('Invalid scene data structure from Claude');
}

// Return parsed scene data
return {
  json: {
    sceneConfig: sceneData.sceneConfig,
    objects: sceneData.objects,
    stats: sceneData.stats,
    prompt: $('Format Model Data').item.json.prompt,
    timestamp: new Date().toISOString()
  }
};

// Get scene data
const sceneData = $input.item.json;
const objects = sceneData.objects;
const config = sceneData.sceneConfig;

// System object GUIDs
const GUID_AUDIO_AMBIENT = "5a38e9cc-262d-4987-90eb-c5197228091c";
const GUID_AUDIO_MAIN = "17ec1d58-e43c-4d03-8217-19eebe8a1991";
const GUID_LIGHT = "f9bd6f60-f538-436b-a520-d2b9dc50b2ed";
const GUID_INTERACTIVE_CUBE = "bfaed1ac-f1f1-49dd-8bc3-431b3d1f1731";
const GUID_PLANE = "bf64aba3-b3c4-4a3d-bf62-474df55255c7";

// Helper function to escape special characters
function escapeXML(str) {
  return str
    .replace(/ /g, '\\ ')
    .replace(/\./g, '\\.')
    .replace(/#/g, '\\#')
    .replace(/\$/g, '\\$');
}

// Helper function to create GUID-based object
function createObject(guid, position, rotation, scale, kwargs = {}) {
  const name = kwargs.name || '';
  const color = kwargs.color || '';
  const trigger = kwargs.trigger || 'None';
  const command = kwargs.command || '';

  const posStr = `${position[0]},${position[1]},${position[2]}`;
  const rotStr = `${rotation[0]},${rotation[1]},${rotation[2]}`;
  const scaleStr = `${scale[0]},${scale[1]},${scale[2]}`;

  return `${guid}~${posStr},${rotStr},${scaleStr}~~smart|True|None|${trigger}|None|||${name}|${color}|||${command}|`;
}

// Helper function to create GLB object
function createGLBObject(url, position, rotation, scale) {
  const posStr = `${position[0]},${position[1]},${position[2]}`;
  const rotStr = `${rotation[0]},${rotation[1]},${rotation[2]}`;
  const scaleStr = `${scale[0]},${scale[1]},${scale[2]}`;

  return `${url},,~${posStr},${rotStr},${scaleStr}~~smart|True|None|None|None||||||||`;
}

// Build system and static objects array
const systemAndStatic = [];

// 1. Add system objects (hidden at y=-10)
systemAndStatic.push(createObject(
  GUID_AUDIO_AMBIENT,
  [-2, -10, 0],
  [0, 0, 0],
  [1, 1, 1],
  { name: 'zPro_AudioAmbientAbility(Clone)' }
));

systemAndStatic.push(createObject(
  GUID_AUDIO_MAIN,
  [2, -10, 2],
  [0, 0, 0],
  [1, 1, 1],
  { name: 'zPro_AudioMain(Clone)' }
));

// 2. Add lighting (2 lights)
const moodColors = {
  peaceful: '#fff8f0',
  energetic: '#ffffff',
  mysterious: '#8080ff'
};
const moodIntensity = {
  peaceful: 0.8,
  energetic: 1.0,
  mysterious: 0.5
};

const lightColor = moodColors[config.mood] || '#ffffff';
const lightIntensity = moodIntensity[config.mood] || 0.8;
const angles = [45, 225];

angles.forEach((angle, i) => {
  const rad = angle * Math.PI / 180;
  const x = 15 * Math.cos(rad);
  const z = 15 * Math.sin(rad);

  const command = `setLightObject\\ "Light${i+1}\\ ,\\ "${lightColor}\\ ,\\ ${lightIntensity}\\ ,\\ "soft\\ ,\\ 15`;

  systemAndStatic.push(createObject(
    GUID_LIGHT,
    [x, 5, z],
    [30, angle, 0],
    [1, 1, 1],
    {
      name: `Light${i+1}`,
      trigger: 'None_DoOnce',
      command: command
    }
  ));
});

// 3. Add ground plane
const area = config.area || 100;
systemAndStatic.push(createObject(
  GUID_PLANE,
  [0, 0, 0],
  [0, 0, 0],
  [area/2, 1, area/2],
  {
    name: 'zprim_Plane(Clone)',
    color: '#FFFFFF00'
  }
));

// 4. Add ambient audio zone
const audioMap = {
  forest: 'https://metaverse.mayaver.com/my-content/forest_ambient.mp3',
  tropical: 'https://metaverse.mayaver.com/my-content/jungle_ambient.mp3',
  jungle: 'https://metaverse.mayaver.com/my-content/jungle_ambient.mp3',
  desert: 'https://metaverse.mayaver.com/my-content/desert_wind.mp3',
  spring: 'https://metaverse.mayaver.com/my-content/spring_birds.mp3'
};
const audioUrl = audioMap[config.environment] || 'https://metaverse.mayaver.com/my-content/nature_ambient.mp3';
const audioCommand = `playAmbientAudio\\ "ambient1",\\ "${audioUrl}",\\ "true",\\ ${area/2},\\ 0.8`;

systemAndStatic.push(createObject(
  GUID_INTERACTIVE_CUBE,
  [0, 1, 0],
  [0, 0, 0],
  [area, 1, area],
  {
    name: 'ambient1',
    color: '#FFFFFF00',
    trigger: 'TriggerEnter',
    command: audioCommand
  }
));

// 5. Build GLB model objects array
const glbModels = [];
objects.forEach(obj => {
  const pos = obj.position;
  const rot = obj.rotation;
  const scale = obj.scale;
  const url = obj.url;

  glbModels.push(createGLBObject(
    url,
    [pos.x, pos.y, pos.z],
    [rot.x, rot.y, rot.z],
    [scale.x, scale.y, scale.z]
  ));
});

// Scene configuration values
const spawnPos = `0,0,${-area/3}`;
const spawnRot = '0,180,0';
const groundType = '5';
const cameraPos = '0,3,0';
const cameraRot = '56.21999,330,0';
const access = 'unlocked';

// Build complete XML following EXACT sample format
// CRITICAL: [SystemObjects];^SpawnPos^SpawnRot^GroundType^^CustomGround^[GLBModels];^CameraConfig^SkyboxSettings^SkyboxModel^Access|

const parts = [];

// Part 1: System objects and static objects (lights, ground, audio zones)
if (systemAndStatic.length > 0) {
  parts.push(systemAndStatic.join(';'));
}

// Part 2: Spawn configuration
parts.push(`^${spawnPos}^${spawnRot}^${groundType}^^false,,^`);

// Part 3: GLB models
if (glbModels.length > 0) {
  parts.push(glbModels.join(';'));
}

// Part 4: Camera and final configuration
parts.push(`^${cameraPos},${cameraRot}^false||||^false||^${access}|`);

// Join all parts with semicolons
let xml = parts.join(';');

// Clean up double semicolons
while (xml.includes(';;')) {
  xml = xml.replace(';;', ';');
}

// Validate: Must have exactly 10 caret (^) markers
const caretCount = (xml.match(/\^/g) || []).length;
if (caretCount !== 10) {
  console.log(`WARNING: Expected 10 carets, found ${caretCount}`);
}

// Return XML and metadata
return {
  json: {
    xml: xml,
    filename: `scene_${Date.now()}.txt`,
    stats: {
      totalObjects: objects.length,
      systemObjects: systemAndStatic.length,
      glbObjects: glbModels.length,
      caretCount: caretCount,
      length: xml.length
    },
    sceneConfig: sceneData.sceneConfig,
    prompt: sceneData.prompt
  }
};

const data = $input.item.json;
const xml = data.xml;

// Validation checks
const validations = {
  hasContent: xml && xml.length > 100,
  endsWithPipe: xml.endsWith('|'),
  hasTenCarets: (xml.match(/\^/g) || []).length === 10,
  hasNoNewlines: !xml.includes('\n') && !xml.includes('\r'),
  hasGLBModels: xml.includes('https://') || xml.includes('http://'),
  hasSystemObjects: xml.split('^')[0].length > 10
};

// Check if all validations pass
const allValid = Object.values(validations).every(v => v);

if (!allValid) {
  const failed = Object.entries(validations)
    .filter(([key, value]) => !value)
    .map(([key]) => key);

  throw new Error(`XML validation failed: ${failed.join(', ')}`);
}

// Return validated data
return {
  json: {
    ...data,
    validated: true,
    validations: validations
  }
};
